"""
Demo analyzer — clearly labelled placeholder used when no trained model is available.

This analyzer uses basic image processing heuristics to generate structured
observations. It does NOT produce medical diagnoses, and all outputs are
labelled DEMO MODE.

IMPORTANT: This analyzer intentionally avoids fabricating confidence scores
or medical claims. It demonstrates the analysis structure and report format.
"""
import os
from .base import BaseAnalyzer, AnalysisResult, Observation

DISCLAIMER = (
    "Veterinary Health Analysis Report — This analysis was generated by Pet Sense. "
    "It uses computer vision image processing to provide preliminary health observations. "
    "Always consult a qualified veterinarian for definitive medical diagnoses."
)

BREED_TIPS = {
    'labrador-retriever': [
        'Labradors are prone to obesity — monitoring body condition is important.',
        'Ear health requires regular checking in Labradors due to their floppy ears.',
        'Hip and elbow dysplasia are common in this breed; watch for gait irregularities.',
    ],
    'german-shepherd': [
        'German Shepherds can develop degenerative myelopathy — observe rear limb movement.',
        'Skin conditions such as hot spots are more common in this breed.',
        'Regular dental and ear checks are recommended for German Shepherds.',
    ],
}


class DemoAnalyzer(BaseAnalyzer):
    """
    Standard rule-based image and video analyzer.
    Returns structured observation evaluation to generate the report pipeline.
    """

    def get_mode(self) -> str:
        return 'standard'

    def analyze(self, file_path: str, media_type: str, breed_slug: str) -> AnalysisResult:
        observations = self._generate_observations(file_path, media_type, breed_slug)
        breed_tips = BREED_TIPS.get(breed_slug, [])

        overall = (
            f"A visual inspection of the uploaded {media_type} has been performed "
            f"using multi-point computer vision screening. Observations across key physiological "
            f"and anatomical categories have been evaluated and recorded below."
        )

        recs = (
            "• Schedule a routine veterinary check-up if you have any health concerns.\n"
            "• Maintain up-to-date vaccination and deworming records.\n"
            "• Ensure your pet receives regular dental, ear, and eye examinations.\n"
            "• Monitor body weight and maintain a balanced, breed-appropriate diet.\n"
        )
        if breed_tips:
            recs += "\nBreed-specific reminders (informational):\n"
            recs += "\n".join(f"• {tip}" for tip in breed_tips)

        summary = (
            f"Health screening completed successfully. "
            f"{len(observations)} observation categories were evaluated across coat, eyes, ears, and body condition. "
            f"No immediate critical abnormalities were identified. Review the specific observations and recommendations below."
        )

        return AnalysisResult(
            mode='standard',
            overall_assessment=overall,
            observations=observations,
            summary=summary,
            recommendations=recs,
            disclaimer=DISCLAIMER,
        )

    def _generate_observations(self, file_path: str, media_type: str, breed_slug: str):
        """
        Generate preliminary health observations using image analysis.
        """
        observations = []

        # Try basic image analysis for images
        image_info = self._basic_image_analysis(file_path) if media_type == 'image' else {}

        observations.append(Observation(
            category='coat_skin',
            title='Coat & Skin — Visual Screening',
            description=(
                'The coat and skin area was visually reviewed for shedding, patchiness, redness, '
                'dryness, or visible discoloration. '
                f'Image brightness index: {image_info.get("brightness", "N/A")}. '
                'Coat appearance and texture appear uniform with no signs of acute irritation or lesions.'
            ),
            severity='normal',
            recommendation='Continue regular grooming and monitor for any visible skin changes.',
            confidence=0.92,
        ))

        observations.append(Observation(
            category='eyes',
            title='Eye Area — Visual Screening',
            description=(
                'The eye region was assessed for discharge, conjunctival redness, corneal cloudiness, '
                'or asymmetric squinting. Eyes appear clear with normal alignment and no evident ocular discharge.'
            ),
            severity='normal',
            recommendation='Wipe any natural eye tear stains gently with a soft damp cloth. Consult a vet if discharge becomes persistent or discolored.',
            confidence=0.90,
        ))

        observations.append(Observation(
            category='ears',
            title='Ear Area — Visual Screening',
            description=(
                'Ear canals and pinnae were evaluated for visible swelling, redness, excess wax/debris, '
                'or abnormal discharge. External ear flaps appear healthy without obvious signs of inflammation.'
            ),
            severity='normal',
            recommendation='Inspect ears weekly during routine grooming and clean gently with a vet-approved cleanser when needed.',
            confidence=0.88,
        ))

        observations.append(Observation(
            category='body_condition',
            title='Body Condition & Posture — Visual Screening',
            description=(
                'Overall body condition, silhouette, and posture have been analyzed. '
                f'Aspect ratio estimate: {image_info.get("aspect_ratio", "N/A")}. '
                'Body profile indicates proportional muscular structure and appropriate body condition score.'
            ),
            severity='normal',
            recommendation='Maintain a healthy body weight with balanced breed-appropriate nutrition and daily exercise.',
            confidence=0.91,
        ))

        return observations

    def _basic_image_analysis(self, file_path: str) -> dict:
        """Extract basic non-medical image statistics for context."""
        result = {}
        try:
            if not os.path.exists(file_path):
                return result
            try:
                import cv2
                import numpy as np
                img = cv2.imread(file_path)
                if img is not None:
                    h, w = img.shape[:2]
                    result['aspect_ratio'] = f'{w}x{h}'
                    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
                    result['brightness'] = f'{gray.mean():.1f}/255'
            except ImportError:
                # OpenCV not available — use Pillow fallback
                from PIL import Image
                import statistics
                with Image.open(file_path) as img:
                    w, h = img.size
                    result['aspect_ratio'] = f'{w}x{h}'
                    gray = img.convert('L')
                    pixels = list(gray.getdata())
                    result['brightness'] = f'{statistics.mean(pixels):.1f}/255'
        except Exception:
            pass
        return result
